 if x['context']!=x['query']:errors.append('exact-context-mismatch')
 if not all(x['supports'].values()):errors.append('missing-qualified-support')
 if x['named_Context_version']!=x['context']['context_version']:errors.append('Context-version-mismatch')
 if x['request_is_Context'] or x['request_is_View']:errors.append('Request-sibling-collapse')
 if x['mutates_Context'] or x['grants_source_authority']:errors.append('Request-caused-mutation-or-authority')
 if x['infers_resolution_authorized'] or x['infers_resolved_View'] or x['infers_inputs_current']:errors.append('request-inferred-outcome')
 if x['actual_claim']:errors.append('actual-claim-unverified')
 return errors
